/** Real PostgreSQL app-role + actual protected original service + isolated provider HTTP; no production data. */
class FinanceInvoiceAutomationIntegrationTest {
 static EmbeddedPostgres pg;static JdbcTemplate admin;static FinanceService finance;static FinanceEvidenceService evidence;static FinanceInvoiceAutomationService automation;static NamedParameterJdbcTemplate named;static HttpServer provider;static DataSourceTransactionManager manager;static Path files;static AtomicInteger posts=new AtomicInteger();static Map<String,Map<String,Object>> responses=new ConcurrentHashMap<>();static volatile boolean uncertain;static volatile String verificationOutcome="VERIFIED";static volatile Map<String,Object> lastPayload;
 static final UUID TENANT=UUID.fromString("10000000-0000-0000-0000-000000000001");UUID hotel,owner,assignment,intake;
 @BeforeAll static void start()throws Exception{pg=EmbeddedPostgres.builder().start();var source=pg.getPostgresDatabase();admin=new JdbcTemplate(source);admin.execute("create role hotel_ai_os_app nologin nosuperuser nobypassrls");Flyway.configure().dataSource(source).locations("classpath:db/migration").target("95").load().migrate();var app=new DelegatingDataSource(source){@Override public Connection getConnection()throws SQLException{var c=super.getConnection();try(var s=c.createStatement()){s.execute("set role hotel_ai_os_app");}return c;}};var jdbc=new JdbcTemplate(app);named=new NamedParameterJdbcTemplate(app);manager=new DataSourceTransactionManager(app);var database=new TenantDatabaseContext(jdbc,true);var access=new AccessPolicy();var audit=new AuditWriter(named,e->{});var accounting=new FinanceAccountingService(named,database,access,audit,FinanceV2Support.JSON);var target=new FinanceService(named,database,access,FinanceV2Support.JSON,audit,accounting);var proxy=new ProxyFactory(target);proxy.setProxyTargetClass(true);proxy.addAdvice(new TransactionInterceptor(manager,new AnnotationTransactionAttributeSource()));finance=(FinanceService)proxy.getProxy();files=Files.createTempDirectory("invoice-automation-test-");evidence=new FinanceEvidenceService(files.toString(),finance,access,new AttachmentMalwareScanner("","",1,true,false));provider=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);provider.createContext("/invoice",exchange->{Map<String,Object> response;int status=200;if(exchange.getRequestMethod().equals("POST")){posts.incrementAndGet();lastPayload=map(JSON.readValue(exchange.getRequestBody().readAllBytes(),Map.class));String request=lastPayload.get("requestId").toString();boolean ocr=lastPayload.get("operation").equals("OCR");response=new LinkedHashMap<>();response.put("provider","isolated-provider");response.put("requestId",request);response.put("sourceSha256",lastPayload.get("sourceSha256"));response.put("externalReference","receipt-"+request);response.put("status",ocr?"CANDIDATES":verificationOutcome);if(ocr)response.put("candidates",Map.of("invoiceCode","","invoiceNumber","00000000000000123456","amount","100.00","buyerTaxNumber","TAX123"));else response.put("invoiceFields",lastPayload.get("invoiceFields"));responses.put(request,response);if(uncertain)status=500;}else{String request=exchange.getRequestURI().getQuery().substring("requestId=".length());response=responses.getOrDefault(request,Map.of("provider","isolated-provider","requestId",request,"status","PENDING"));}byte[] bytes=json(response).getBytes(StandardCharsets.UTF_8);exchange.sendResponseHeaders(status,bytes.length);exchange.getResponseBody().write(bytes);exchange.close();});provider.start();var gateway=new FinanceInvoiceAutomationGateway("http://127.0.0.1:"+provider.getAddress().getPort()+"/invoice","http://127.0.0.1:"+provider.getAddress().getPort()+"/invoice","test-key","isolated-provider");automation=new FinanceInvoiceAutomationService(named,database,access,audit,finance,evidence,gateway,manager);}
 @AfterAll static void stop()throws Exception{if(provider!=null)provider.stop(0);if(pg!=null)pg.close();}
 @AfterEach void clear(){TenantContext.clear();}
 @BeforeEach void seed()throws Exception{uncertain=false;verificationOutcome="VERIFIED";posts.set(0);hotel=UUID.randomUUID();owner=UUID.randomUUID();assignment=UUID.randomUUID();intake=UUID.randomUUID();admin.update("insert into org_unit(id,tenant_id,code,name,unit_type) values(?,?,?,'OCR隔离门店','HOTEL')",hotel,TENANT,hotel.toString());admin.update("insert into org_unit_closure(tenant_id,ancestor_id,descendant_id,depth) values(?,?,?,0)",TENANT,hotel,hotel);admin.update("insert into user_account(id,tenant_id,login_name,display_name) values(?,?,?,'隔离收票员工')",owner,TENANT,owner.toString());UUID employee=UUID.randomUUID();admin.update("insert into employee(id,tenant_id,account_id,employee_no,name) values(?,?,?,?,'隔离收票员工')",employee,TENANT,owner,employee.toString());admin.update("insert into employee_position_assignment(id,tenant_id,employee_id,org_unit_id,position_id,valid_from) select ?,?,?,?,id,current_date from position_definition where tenant_id=? limit 1",assignment,TENANT,employee,hotel,TENANT);as(owner,Set.of(hotel),Set.of(assignment),"finance.submit");finance.createIntake(new FinanceModels.Create(intake,assignment));var image=new java.awt.image.BufferedImage(2,1,java.awt.image.BufferedImage.TYPE_INT_RGB);var bytes=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(image,"png",bytes);evidence.uploadIntake(intake,new MockMultipartFile("file","test.png","image/png",bytes.toByteArray()));}
 @Test void actualOcrCreatesImmutableCandidatesWithoutOverwritingUntilExplicitOwnerAdoption(){var current=finance.intakeDetail(intake);UUID request=UUID.randomUUID();automation.start(intake,command(current,request,"OCR"));assertThat(lastPayload).containsKey("originalBase64");var unchanged=finance.intakeDetail(intake);assertThat(unchanged).containsEntry("invoiceNumber","").containsEntry("confirmed",false);var adopted=automation.adopt(intake,request,new FinanceInvoiceAutomationModels.Adopt(((Number)unchanged.get("version")).intValue(),true));assertThat(adopted).containsEntry("invoiceNumber","00000000000000123456").containsEntry("amount","100.00").containsEntry("confirmed",false);assertThat(admin.queryForObject("select count(*) from fia_proof where job_id=?",Integer.class,request)).isOne();assertThatThrownBy(()->admin.update("update fia_proof set outcome='VERIFIED' where job_id=?",request)).hasMessageContaining("append-only");assertThatThrownBy(()->automation.adopt(intake,request,new FinanceInvoiceAutomationModels.Adopt(((Number)adopted.get("version")).intValue(),true))).hasMessageContaining("已采纳");}
 @Test void externalVerificationBindsExactFieldsAndChangingAmountInvalidatesCurrentProof(){confirmed();var current=finance.intakeDetail(intake);UUID request=UUID.randomUUID();automation.start(intake,command(current,request,"VERIFY"));assertThat(lastPayload).doesNotContainKey("originalBase64");assertThat(finance.intakeDetail(intake)).containsEntry("verificationStatus","EXTERNAL_VERIFIED");verificationOutcome="INVALID";automation.start(intake,command(current,UUID.randomUUID(),"VERIFY"));assertThat(finance.intakeDetail(intake)).containsEntry("verificationStatus","EXTERNAL_FAILED");finance.saveIntake(intake,new FinanceModels.IntakeDraft(((Number)current.get("version")).intValue(),"","00000000000000123456",new BigDecimal("101.00"),"TAX123",true));assertThat(finance.intakeDetail(intake)).containsEntry("verificationStatus","NOT_VERIFIED");var rows=FinanceV2Support.rows(automation.jobs(intake).get("items"));assertThat(rows.getFirst()).containsEntry("matchesCurrentSource",false);}
 @Test void uncertainProviderResultQueriesOriginalRequestWithoutRetransmitting(){confirmed();var current=finance.intakeDetail(intake);UUID request=UUID.randomUUID();uncertain=true;assertThatThrownBy(()->automation.start(intake,command(current,request,"VERIFY"))).hasMessageContaining("尚不确定");assertThat(admin.queryForObject("select status from fia_job where id=?",String.class,request)).isEqualTo("UNKNOWN");assertThatThrownBy(()->automation.start(intake,command(current,UUID.randomUUID(),"VERIFY"))).hasMessageContaining("查询原请求");uncertain=false;automation.refresh(intake,request);assertThat(posts.get()).isOne();assertThat(finance.intakeDetail(intake)).containsEntry("verificationStatus","EXTERNAL_VERIFIED");}
 @Test void missingConsentStaleHashCrossOwnerAndMissingConnectionCannotTransmit(){var current=finance.intakeDetail(intake);var in=command(current,UUID.randomUUID(),"OCR");assertThatThrownBy(()->automation.start(intake,new FinanceInvoiceAutomationModels.Start(in.requestId(),"OCR",in.expectedIntakeVersion(),in.sourceSha256(),false,"未授权"))).hasMessageContaining("明确");assertThatThrownBy(()->automation.start(intake,new FinanceInvoiceAutomationModels.Start(UUID.randomUUID(),"OCR",in.expectedIntakeVersion(),"0".repeat(64),true,"测试"))).hasMessageContaining("版本已变化");UUID stranger=UUID.randomUUID();as(stranger,Set.of(UUID.randomUUID()),Set.of(),"finance.submit");assertThatThrownBy(()->automation.jobs(intake)).isInstanceOf(RuntimeException.class);assertThat(posts.get()).isZero();assertThatThrownBy(()->new FinanceInvoiceAutomationGateway("","","","").call("OCR",UUID.randomUUID(),Map.of(),false)).hasMessageContaining("未配置");}
 private void confirmed(){var current=finance.intakeDetail(intake);finance.saveIntake(intake,new FinanceModels.IntakeDraft(((Number)current.get("version")).intValue(),"","00000000000000123456",new BigDecimal("100.00"),"TAX123",true));}
 private FinanceInvoiceAutomationModels.Start command(Map<String,Object> current,UUID request,String operation){return new FinanceInvoiceAutomationModels.Start(request,operation,((Number)current.get("version")).intValue(),current.get("sha256").toString(),true,"隔离测试原件，仅发送本机HTTP stub");}
 private void as(UUID actor,Set<UUID> scopes,Set<UUID> assignments,String...permissions){TenantContext.set(new TenantPrincipal(TENANT,actor,"TEST",Set.of("TEST"),Set.of(permissions),scopes,assignments,false,UUID.randomUUID()));}
}
